Props schema: {"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"content":{"type":"string","minLength":1,"maxLength":240},"tone":{"type":"string","enum":["neutral","positive","caution","negative","accent"]}},"required":["content"],"additionalProperties":false}
